package com.rin23.app;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;
public final class PackArchiveTest {
 static void ok(boolean v,String s){if(!v)throw new AssertionError(s);}
 static byte[] manifest(int n){return ("{\"format_version\":2,\"header\":{\"name\":\"ทดสอบ "+n+"\",\"uuid\":\"00000000-0000-4000-8000-"+String.format("%012d",n)+"\",\"version\":[1,0,0]},\"modules\":[{\"type\":\"resources\",\"uuid\":\"10000000-0000-4000-8000-"+String.format("%012d",n)+"\",\"version\":[1,0,0]}]}").getBytes(StandardCharsets.UTF_8);}
 static byte[] zip(String[] names,byte[][] data)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){for(int i=0;i<names.length;i++){z.putNextEntry(new ZipEntry(names[i]));z.write(data[i]);z.closeEntry();}}return b.toByteArray();}
 static int serial;static File source(File dir,byte[] data)throws Exception{File f=new File(dir,"source-"+(serial++)+".zip");Files.write(f.toPath(),data);return f;}
 static void fails(File dir,File out,byte[] bytes,String message)throws Exception{try{PackArchive.prepare(source(dir,bytes),out,"bad.zip");throw new AssertionError(message);}catch(IOException expected){}ok(out.list().length==0,"temporary outputs cleaned after "+message);}
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("rin-import-test").toFile(),inputs=new File(root,"inputs"),out=new File(root,"out");inputs.mkdir();out.mkdir();byte[] data="hello!".getBytes(StandardCharsets.UTF_8),one=zip(new String[]{"manifest.json","textures/test.txt"},new byte[][]{manifest(1),data});
  File original=source(inputs,one),pack=PackArchive.prepare(original,out,"addon.zip");ok(pack.getName().endsWith(".mcpack"),"ZIP root converted to mcpack");try(ZipFile z=new ZipFile(pack)){ok(z.getEntry("manifest.json")!=null&&z.getEntry("textures/test.txt")!=null,"all root content preserved");}ok(Arrays.equals(Files.readAllBytes(original.toPath()),one),"source untouched");byte[] normalized=Files.readAllBytes(pack.toPath());pack.delete();
  pack=PackArchive.prepare(source(inputs,zip(new String[]{"Wrapper/manifest.json","Wrapper/textures/test.txt","README.txt"},new byte[][]{manifest(1),data,data})),out,"wrapped.zip.zip");ok(Arrays.equals(normalized,Files.readAllBytes(pack.toPath())),"wrapper removed and deterministic output for duplicate hash");pack.delete();
  File bundle=PackArchive.prepare(source(inputs,zip(new String[]{"BP/manifest.json","RP/manifest.json"},new byte[][]{manifest(1),manifest(2)})),out,"addon.mcaddon.zip");ok(bundle.getName().endsWith(".mcaddon"),"two manifests bundled");try(ZipFile z=new ZipFile(bundle)){ok(z.size()==2&&z.getEntry("pack-1.mcpack")!=null,"standard mcpack children");}bundle.delete();
  bundle=PackArchive.prepare(source(inputs,zip(new String[]{"A/pack.mcpack","B/pack.mcpack"},new byte[][]{one,zip(new String[]{"manifest.json"},new byte[][]{manifest(2)})})),out,"nested.mcaddon");try(ZipFile z=new ZipFile(bundle)){ok(z.size()==2,"same nested basename never overwrites sibling");}bundle.delete();
  byte[] innerBundle=zip(new String[]{"one.mcpack","two.mcpack"},new byte[][]{one,one});bundle=PackArchive.prepare(source(inputs,zip(new String[]{"bundle.mcaddon","third.mcpack"},new byte[][]{innerBundle,one})),out,"flatten.zip");try(ZipFile z=new ZipFile(bundle)){ok(z.size()==3,"nested bundles flattened to three packs");Enumeration<? extends ZipEntry> e=z.entries();while(e.hasMoreElements())ok(e.nextElement().getName().endsWith(".mcpack"),"no mcaddon inside mcaddon");}bundle.delete();
  fails(inputs,out,zip(new String[]{"readme.txt"},new byte[][]{data}),"not Minecraft");fails(inputs,out,new byte[]{1,2,3},"broken ZIP");fails(inputs,out,zip(new String[]{"manifest.json","../escape"},new byte[][]{manifest(1),data}),"path traversal");fails(inputs,out,zip(new String[]{"manifest.json","/absolute"},new byte[][]{manifest(1),data}),"absolute path");fails(inputs,out,zip(new String[]{"manifest.json","a\\b"},new byte[][]{manifest(1),data}),"backslash path");fails(inputs,out,zip(new String[]{"manifest.json","A.txt","a.txt"},new byte[][]{manifest(1),data,data}),"case duplicate");fails(inputs,out,zip(new String[]{"manifest.json"},new byte[][]{"{}".getBytes(StandardCharsets.UTF_8)}),"invalid manifest");fails(inputs,out,zip(new String[]{"manifest.json","nested/manifest.json"},new byte[][]{manifest(1),manifest(2)}),"ambiguous manifest tree");
  byte[] deep=one;for(int i=0;i<4;i++)deep=zip(new String[]{"nested.zip"},new byte[][]{deep});fails(inputs,out,deep,"recursion depth");
  ByteArrayOutputStream corrupt=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(corrupt)){ZipEntry m=new ZipEntry("manifest.json");z.putNextEntry(m);z.write(manifest(1));z.closeEntry();ZipEntry e=new ZipEntry("test.txt");CRC32 crc=new CRC32();crc.update(data);e.setMethod(ZipEntry.STORED);e.setSize(data.length);e.setCompressedSize(data.length);e.setCrc(crc.getValue());z.putNextEntry(e);z.write(data);z.closeEntry();}byte[] bad=corrupt.toByteArray();for(int i=0;i<bad.length-data.length;i++)if(bad[i]=='h'&&bad[i+1]=='e'&&bad[i+2]=='l'){bad[i]='X';break;}fails(inputs,out,bad,"CRC mismatch");
  PackArchive.Budget budget=new PackArchive.Budget();budget.add((int)PackArchive.MAX_EXPANDED);try{budget.add(1);throw new AssertionError("expanded bytes limit");}catch(IOException expected){}
  ok(PackArchive.safeName("addon.mcaddon.zip.zip").equals("addon"),"strip redundant extension");ok(!PackArchive.safeName("../../name.zip").contains("/"),"safe output basename");
  System.out.println("PASS: real ZIP root/wrapper/multipart/nested formats, deterministic duplicate identity, original preserved, path/CRC/manifest/depth/budget errors, cleanup and sibling collision protection");
 }
}
